// Signs release builds with the ClipTube upload key when CLIPTUBE_KEYSTORE is set (local builds and the
// GitHub release workflow), and with the debug key otherwise. The android/ folder is generated by
// `expo prebuild`, so this edit has to live in a config plugin rather than in build.gradle itself.
const { withAppBuildGradle } = require('expo/config-plugins');

const RELEASE_CONFIG = `
        release {
            if (System.getenv('CLIPTUBE_KEYSTORE')) {
                storeFile file(System.getenv('CLIPTUBE_KEYSTORE'))
                storePassword System.getenv('CLIPTUBE_KEYSTORE_PASSWORD')
                keyAlias System.getenv('CLIPTUBE_KEY_ALIAS') ?: 'cliptube'
                keyPassword System.getenv('CLIPTUBE_KEY_PASSWORD') ?: System.getenv('CLIPTUBE_KEYSTORE_PASSWORD')
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let src = cfg.modResults.contents;
    if (src.includes("System.getenv('CLIPTUBE_KEYSTORE')")) return cfg;
    if (!/signingConfigs\s*\{/.test(src)) throw new Error('withReleaseSigning: no signingConfigs block in app/build.gradle');
    src = src.replace(/signingConfigs\s*\{/, (m) => `${m}${RELEASE_CONFIG}`);
    // In the release build type, use the upload key when it is configured.
    const release = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
    if (!release.test(src)) throw new Error('withReleaseSigning: release build type not found in app/build.gradle');
    src = src.replace(release, "$1signingConfig System.getenv('CLIPTUBE_KEYSTORE') ? signingConfigs.release : signingConfigs.debug");
    cfg.modResults.contents = src;
    return cfg;
  });
};
